-- TPC-DS Test_Query Query 488
-- Based on: query63.tpl (medium)
-- Variation: 80

 select  * from (select i_manager_id ,sum(ss_sales_price) sum_sales ,avg(sum(ss_sales_price)) over (partition by i_manager_id) avg_monthly_sales from item ,store_sales ,date_dim ,store where ss_item_sk = i_item_sk and ss_sold_date_sk = d_date_sk and ss_store_sk = s_store_sk and d_month_seq in (2,18+1,17+1,23+5,36+6,33+4,30+5,49+6,48+6,101+8,38+12,76+12) and ((    i_category in ('Books','Children','Electronics') and i_class in ('personal','portable','reference','self-help') and i_brand in ('scholaramalgamalg #11','scholaramalgamalg #5', 'exportiunivamalg #9','scholaramalgamalg #9')) or(    i_category in ('Women','Music','Men') and i_class in ('accessories','classical','fragrances','pants') and i_brand in ('amalgimporto #2','edu packscholar #2','exportiimporto #1', 'importoamalg #1'))) group by i_manager_id, d_moy) tmp1 where case when avg_monthly_sales > 1 then abs (sum_sales - avg_monthly_sales) / avg_monthly_sales else null end > 0.2 order by i_manager_id ,avg_monthly_sales ,sum_sales limit 102;
